// Isolated design review. Illustrative data only; no application APIs or writes.
const icons={search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',menu:'<path d="M4 7h16M4 12h16M4 17h16"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21c0-7 16-7 16 0"/>',x:'<path d="m6 6 12 12M6 18 18 6"/>',pin:'<path d="M19 10c0 6-7 11-7 11S5 16 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2.5"/>',map:'<path d="m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2V5Zm6-2v16m6-14v16"/>',list:'<path d="M9 6h12M9 12h12M9 18h12M3 6h1M3 12h1M3 18h1"/>',filter:'<path d="M4 6h16M4 18h16M4 12h16"/><circle cx="8" cy="6" r="2" fill="#faf7f1"/><circle cx="16" cy="12" r="2" fill="#faf7f1"/><circle cx="9" cy="18" r="2" fill="#faf7f1"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',up:'<path d="M6 18 18 6M6 6h12v12"/>',locate:'<path d="m21 3-7 18-4-7-7-4 18-7Z"/>',scissors:'<circle cx="6" cy="6" r="3"/><circle cx="6" cy="18" r="3"/><path d="m9 8 11 12M9 16 20 4"/>',lotus:'<path d="M12 21C4 19 2 14 3 10c4 0 7 3 9 11Zm0 0c8-2 10-7 9-11-4 0-7 3-9 11Zm0 0C7 15 7 8 12 3c5 5 5 12 0 18Z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>'};
const svg=(name)=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.map}</svg>`;
const branch='<svg viewBox="0 0 80 110" fill="none" aria-hidden="true"><path d="M8 105Q42 73 66 7M31 77Q17 55 12 50Q28 55 35 68M39 63Q21 38 21 31Q40 43 44 51M48 43Q35 21 39 15Q51 28 52 33M54 33Q65 13 75 9Q72 25 54 33M46 51Q61 33 76 34Q66 47 46 51M36 69Q53 54 71 61Q56 72 36 69M25 85Q42 76 57 82Q47 89 25 85M61 18Q58 7 64 2Q66 13 61 18"/></svg>';
const params=new URLSearchParams(location.search), state=params.get('state')||'selected';
let mode=params.get('view')||(['list','empty','error','loading','group','more-error'].includes(state)?'list':'map');
let selected=['selected','master','no-time','details-error','details-loading','long'].includes(state)?(state==='master'?1:0):-1;
let category='Все услуги',soon=false,more=false,group=state==='group';
const people=[{name:'Maison',kind:'Салон',category:'Уход за лицом · Косметология',address:'ул. Патриаршие Пруды, 12',lat:55.764,lng:37.592},{name:'Анна Белова',kind:'Мастер',category:'Визаж · Брови · Макияж',address:'ул. Малая Бронная, 8',lat:55.759,lng:37.601},{name:'Студия Линия',kind:'Салон',category:'Маникюр · Педикюр',address:'ул. Остоженка, 25',lat:55.746,lng:37.597},{name:'Елена',kind:'Мастер',category:'Маникюр',address:'ул. Тверская, 15',lat:55.757,lng:37.619},{name:'Студия Уход',kind:'Салон',category:'Волосы',address:'ул. Тверская, 15',lat:55.757,lng:37.619},{name:'Мария',kind:'Мастер',category:'Брови',address:'ул. Тверская, 15',lat:55.757,lng:37.619}];
const categories=['Все услуги','Макияж','Маникюр','Брови','Ресницы','Волосы','Косметология','Массаж','Татуировки'];
const avatar=(p,i)=>`<div class="avatar ${i===1?'master':i===2?'third':''}" role="img" aria-label="${p.kind==='Мастер'?'Фото':'Логотип'} — пример из утверждённого макета"></div>`;
document.querySelector('#app').innerHTML=`<header class="header"><a class="brand" href="#" aria-label="Luma Beauty"> <span>Luma<small>BEAUTY</small></span>${branch}</a><nav aria-label="Основная навигация"><a href="#" data-demo>Мастера</a><a href="#" data-demo>Вдохновение</a><a href="#" class="active">Карта</a></nav><div class="actions"><button class="icon search-action" aria-label="Поиск" data-demo>${svg('search')}</button><button class="icon account" aria-label="Кабинет" data-demo>${svg('user')}<span>Войти</span></button><button class="icon menu-button" id="menu" aria-label="Открыть меню">${svg('menu')}</button></div></header><section class="toolbar" aria-label="Поиск и вид карты"><label class="search">${svg('search')}<input value="Москва" aria-label="Город, мастер или салон" placeholder="Город, мастер или салон"></label><div class="field">${svg('lotus')}<select aria-label="Направление">${categories.map(x=>`<option>${x}</option>`).join('')}</select></div><label class="soon"><input type="checkbox"><span>Есть время в ближайший час</span></label><button class="filter-toggle" id="filters" aria-label="Открыть фильтры">${svg('filter')}<span>Фильтры</span></button><div class="view-switch" aria-label="Вид результатов"><button id="list-tab">${svg('list')}Список</button><button id="map-tab">${svg('map')}Карта</button></div></section><main class="layout"><aside class="sidebar"><div class="intro"><h1>Красота <em>рядом.</em></h1><p id="count"></p></div><div id="results"></div></aside><section class="map-area" aria-label="Карта мастеров и салонов"><div class="map" id="map"></div><span class="mobile-caption" id="map-count">В этой области: 6</span><button class="icon location" id="locate" aria-label="Найти мастеров рядом">${svg('locate')}</button><div id="selection"></div><div id="notice" role="status"></div></section></main><div id="portal"></div>`;
document.querySelectorAll('[data-demo],.brand').forEach(el=>el.addEventListener('click',e=>{e.preventDefault();notice('Это макет для согласования. Переходы на площадку появятся при переносе UI.')}));
const map=L.map('map',{zoomControl:false,attributionControl:false,scrollWheelZoom:false}).setView([55.754,37.604],14);
L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:18,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap contributors</a>'}).addTo(map);
L.control.attribution({prefix:false}).addTo(map);L.control.zoom({position:'topright'}).addTo(map);
const layer=L.layerGroup().addTo(map);
function markers(){layer.clearLayers();people.slice(0,3).forEach((p,i)=>L.marker([p.lat,p.lng],{icon:L.divIcon({className:'pin-icon',html:`<span class="pin ${i!==1?'salon':''} ${selected===i?'chosen':''}">${svg(i===1?'scissors':'lotus')}</span>`,iconSize:[40,46],iconAnchor:[20,46]})}).addTo(layer).on('click',()=>choose(i)));L.marker([55.757,37.619],{icon:L.divIcon({className:'pin-icon',html:'<span class="cluster">3</span>',iconSize:[48,48]})}).addTo(layer).on('click',()=>{group=true;mode='list';render()})}
function row(p,i){return `<button class="result ${selected===i?'selected':''}" data-person="${i}">${avatar(p,i)}<div><span class="badge ${p.kind==='Мастер'?'master':''}">${p.kind}</span><h2>${p.name}</h2><p class="meta">${p.category}</p><p class="address">${svg('pin')}<span>${p.address}<br>Москва</span></p>${soon?'<p class="meta">Ближайшая запись · 17:00</p>':''}<span class="text-link">Подробнее ${svg('up')}</span></div></button>`}
function render(){document.body.classList.toggle('map-list-only',mode==='list');document.querySelector('#list-tab').classList.toggle('active',mode==='list');document.querySelector('#map-tab').classList.toggle('active',mode==='map');document.querySelector('#list-tab').setAttribute('aria-pressed',String(mode==='list'));document.querySelector('#map-tab').setAttribute('aria-pressed',String(mode==='map'));document.querySelector('#count').textContent=state==='loading'?'Ищем в этой области…':group?'В этом месте: 3':state==='empty'?'В этой области: 0':'В этой области: 6';document.querySelector('#map-count').textContent=group?'В этом месте: 3':'В этой области: 6';
let content=group?`<button class="group-reset" id="reset-group">${svg('arrow')}Все в этой области</button>`:'';
if(state==='loading')content+='<div class="skeleton"></div><div class="skeleton"></div><div class="skeleton"></div>';
else if(state==='empty')content+=`<div class="status">${svg('search')}<h2>Здесь пока никого нет</h2><p>Передвиньте карту или измените поиск. Можно также сбросить направление и фильтр времени.</p><button class="primary" id="retry">Сбросить фильтры</button></div>`;
else if(state==='error')content+=`<div class="status">${svg('map')}<h2>Не удалось загрузить места</h2><p>Проверьте подключение и попробуйте ещё раз. Карта и выбранные фильтры останутся на месте.</p><button class="primary" id="retry">Повторить</button></div>`;
else {content+=`<div class="results">${(group?people.slice(3):people.slice(0,3)).map((p,i)=>row(p,group?i+3:i)).join('')}${more&&!group?people.slice(3).map((p,i)=>row(p,i+3)).join(''):''}</div>`;content+=state==='more-error'?`<div class="small-message">Не удалось обновить список. Уже показанные места остаются на экране.</div><button class="more" id="more">Обновить список</button>`:!more&&!group?'<button class="more" id="more">Показать ещё</button>':'';content+=`<p class="loaded">Показано: ${more&&!group?6:3} из ${group?3:6}</p>`}
document.querySelector('#results').innerHTML=content;document.querySelectorAll('[data-person]').forEach(el=>el.onclick=()=>choose(Number(el.dataset.person)));document.querySelector('#reset-group')?.addEventListener('click',()=>{group=false;render()});document.querySelector('#more')?.addEventListener('click',()=>{more=true;render()});document.querySelector('#retry')?.addEventListener('click',()=>location.href='?view=list');card();if(mode==='map')requestAnimationFrame(()=>{map.invalidateSize();map.setView(innerWidth<801?[55.7615,37.598]:[55.755,37.605],14,{animate:false});markers();if(selected>=0&&innerWidth>800){const point=map.latLngToContainerPoint([people[selected].lat,people[selected].lng]);map.panBy(point.subtract(L.point(Math.min(map.getSize().x-95,510),190)),{animate:false})}});}
function choose(i){selected=i;mode='map';render()}
function card(){const el=document.querySelector('#selection');if(selected<0){el.innerHTML='';return}const p=people[selected];let detail=state==='details-error'?'<p class="small-message">Не удалось проверить ближайшее время.</p><button class="text-link" id="retry-details">Повторить</button>':state==='details-loading'?'<p class="small-message" role="status">Ищем ближайшее время…</p>':state==='no-time'?'<p class="small-message">Нет свободного времени в ближайшие 7 дней.</p>':`<div class="slot"><div><span>Ближайшая запись</span><strong>Сегодня, 17:00</strong></div><p>${selected===1?'Макияж':'Уход за лицом'}</p><footer><span>60 мин${selected===0?' · Мария':''}</span><strong>2 000 ₽</strong></footer></div>`;
el.innerHTML=`<article class="card" aria-label="Выбранный ${p.kind.toLowerCase()}"><button class="icon close" id="close-card" aria-label="Закрыть карточку">${svg('x')}</button><div class="card-top">${avatar(p,selected)}<div><span class="badge ${p.kind==='Мастер'?'master':''}">${p.kind}</span><h2>${state==='long'?'Студия красоты и бережного ухода «Место для себя»':p.name}</h2></div></div><p class="category">${p.category}</p><p class="address">${svg('pin')}<span>Москва · ${p.address}</span></p>${detail}${!['details-error','details-loading'].includes(state)?`<button class="primary" data-book>${state==='no-time'?'Посмотреть расписание':'Записаться'}${svg('arrow')}</button>`:''}<button class="profile-link" data-book>Страница ${p.kind==='Мастер'?'мастера':'салона'} ${svg('up')}</button></article>`;document.querySelector('#close-card').onclick=()=>{selected=-1;card();markers()};document.querySelectorAll('[data-book]').forEach(el=>el.onclick=()=>notice('В реализации откроется существующая страница или запись с выбранной услугой, временем и сотрудником.'));document.querySelector('#retry-details')?.addEventListener('click',()=>location.href='?state=selected');}
function notice(text){document.querySelector('#notice').innerHTML=`<div class="map-notice ${selected>=0?'card-message':''}">${text}</div>`;setTimeout(()=>document.querySelector('#notice').innerHTML='',5500)}
function dialog(menu=false){const portal=document.querySelector('#portal');portal.innerHTML=`<div class="overlay"><section class="sheet" role="dialog" aria-modal="true" aria-labelledby="sheet-title"><span class="drag-handle"></span><button class="icon close" id="close-sheet" aria-label="Закрыть">${svg('x')}</button><h2 id="sheet-title">${menu?'Luma Beauty':'Фильтры'}</h2>${menu?`<div class="menu-links"><button data-link>Мастера ${svg('up')}</button><button data-link>Вдохновение ${svg('up')}</button><button data-link>Карта ${svg('up')}</button><button data-link>Войти ${svg('up')}</button></div>`:`<label for="category-select">Направление</label><div class="field"><select id="category-select">${categories.map(c=>`<option ${c===category?'selected':''}>${c}</option>`).join('')}</select></div><label class="soon"><input id="soon-select" type="checkbox" ${soon?'checked':''}><span>Есть время в ближайший час</span></label><p class="small-message">Результаты обновляются в видимой области карты.</p><div class="sheet-actions"><button class="primary" id="apply">Показать результаты ${svg('arrow')}</button><button class="reset" id="reset">Сбросить фильтры</button></div>`}</section></div>`;const close=()=>{portal.innerHTML='';document.querySelector(menu?'#menu':'#filters').focus()};document.querySelector('#close-sheet').onclick=close;portal.querySelector('.overlay').onclick=e=>{if(e.target.classList.contains('overlay'))close()};document.querySelectorAll('[data-link]').forEach(e=>e.onclick=close);document.querySelector('#apply')?.addEventListener('click',()=>{category=document.querySelector('#category-select').value;soon=document.querySelector('#soon-select').checked;document.querySelector('.toolbar select').value=category;document.querySelector('.toolbar .soon input').checked=soon;close();render()});document.querySelector('#reset')?.addEventListener('click',()=>{document.querySelector('#category-select').value='Все услуги';document.querySelector('#soon-select').checked=false});document.querySelector('#close-sheet').focus();}
document.querySelector('#list-tab').onclick=()=>{mode='list';render()};document.querySelector('#map-tab').onclick=()=>{mode='map';render()};document.querySelector('#filters').onclick=()=>dialog();document.querySelector('#menu').onclick=()=>dialog(true);document.querySelector('#locate').onclick=()=>notice('При переносе сюда останется существующая геолокация. При отказе можно искать по городу вручную.');document.querySelector('.toolbar select').onchange=e=>{category=e.target.value;render()};document.querySelector('.toolbar .soon input').onchange=e=>{soon=e.target.checked;render()};document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(document.querySelector('.overlay'))document.querySelector('#close-sheet').click();else{selected=-1;card();markers()}}});
render();if(state==='filters')dialog();if(state==='geo-denied')notice('Геолокация недоступна. Введите город в поиске или передвиньте карту.');if(state==='tiles-error')notice('Подложка карты временно недоступна. Список мест работает — откройте «Список».');
